import pyomo.environ as pyo

DATA = {
    "mixes": ["first", "second"],
    # fraction of each snack type used per kg of each mix
    "cat_paw_fraction": {"first": 0.20, "second": 0.35},
    "gold_shark_fraction": {"first": 0.80, "second": 0.65},
    # available raw snacks (kg)
    "cat_paw_available": 20,
    "gold_shark_available": 50,
    # profit per kg of each mix ($)
    "profit_per_kg": {"first": 12, "second": 15},
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # --- Sets ---
    model.MIX = pyo.Set(initialize=d["mixes"], ordered=True)

    # --- Variables ---
    model.mix_amount = pyo.Var(
        model.MIX,
        domain=pyo.NonNegativeReals,
        bounds=(0, None),
    )

    # --- Objective: maximize total profit ---
    def obj_rule(m):
        return sum(d["profit_per_kg"][mix] * m.mix_amount[mix] for mix in m.MIX)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # --- Constraints ---
    def cat_paw_rule(m):
        return sum(
            d["cat_paw_fraction"][mix] * m.mix_amount[mix] for mix in m.MIX
        ) <= d["cat_paw_available"]

    model.cat_paw_limit = pyo.Constraint(rule=cat_paw_rule)

    def gold_shark_rule(m):
        return sum(
            d["gold_shark_fraction"][mix] * m.mix_amount[mix] for mix in m.MIX
        ) <= d["gold_shark_available"]

    model.gold_shark_limit = pyo.Constraint(rule=gold_shark_rule)

    return model
